// V36.66.9 · Johto: todas las ventanas de navegación se pueden cerrar tocando el fondo oscuro.
// Se dispara el mismo botón Cerrar de cada componente para conservar exactamente su lógica de retorno,
// pausas automáticas y ventanas anidadas. Las decisiones de gameplay (recompensas, evoluciones, eventos,
// Centro Pokémon, combates/resultados de Gimnasio y celebraciones) quedan fuera deliberadamente.
const JOHTO_BACKDROP_CLOSABLE_IDS=new Set([
  "regionSelectOverlay","checkpointSelectOverlay","pokedexOverlay","pcBoxOverlay","pcSwapOverlay",
  "pokemonDetailOverlay","skillTreeOverlay","optionsOverlay","achievementsOverlay","achievementTmChoiceOverlay",
  "playerProfileOverlay","dexLoreOverlay","enemyDetailOverlay","itemEquipOverlay","incenseInventoryOverlay",
  "mintInventoryOverlay","mintUseOverlay","mtGachaOverlay","tmEquipOverlay","patchNotesOverlay",
  "uxWhyOverlay","uxCompareOverlay","saveTransferOverlay","pkBackupOverlay","pkCloudOverlay",
  "pkCloudConflictOverlay","pkCasinoOverlay","gymSelectOverlay"
]);
function johtoCloseSurfaceFromBackdrop(surface){
  if(!surface||surface.classList.contains("hidden"))return false;
  if(surface===lootPanel){closeInventory();johtoSyncUiPause();return true;}
  const info=el("infoPanel",game);
  if(surface===info){const b=el("infoCloseBtn",game);if(b)b.click();else info.classList.add("hidden");johtoSyncUiPause();return true;}
  const closeBtn=surface.querySelector(
    '#playerProfileCloseBtn,#pokedexCloseBtn,#pcBoxCloseBtn,#pcSwapCloseBtn,#pokemonDetailCloseBtn,'+
    '#skillTreeCloseBtn,#optionsCloseBtn,#achievementsCloseBtn,#achievementTmChoiceCloseBtn,'+
    '#dexLoreCloseBtn,#enemyDetailCloseBtn,#itemEquipCloseBtn,#incenseInventoryCloseBtn,'+
    '#mintInventoryCloseBtn,#mintUseCloseBtn,#mtGachaCloseBtn,#tmEquipCloseBtn,#patchNotesCloseBtn,'+
    '#uxWhyClose,#uxCompareClose,#saveTransferCloseBtn,#pkBackupCloseBtn,#pkCloudCloseBtn,'+
    '#pkCloudConflictCancel,#pkCasinoClose,#gymSelectCloseBtn,#checkpointSelectCloseBtn,#regionSelectCloseBtn'
  );
  if(closeBtn&&!closeBtn.disabled){closeBtn.click();johtoSyncUiPause();return true;}
  surface.classList.add("hidden");johtoSyncUiPause();return true;
}
function johtoInstallBackdropClose(){
  if(!root||root.dataset.jBackdropCloseBound==="1")return;
  root.dataset.jBackdropCloseBound="1";
  root.addEventListener("click",e=>{
    const target=e.target;if(!(target instanceof Element))return;
    // Overlays a pantalla completa: solo el propio fondo cuenta como click exterior.
    if(target===e.currentTarget)return;
    const overlay=target.matches(".overlay,.evo-overlay")?target:null;
    if(overlay&&JOHTO_BACKDROP_CLOSABLE_IDS.has(overlay.id)&&!overlay.classList.contains("hidden")){
      e.preventDefault();e.stopPropagation();e.stopImmediatePropagation?.();johtoCloseSurfaceFromBackdrop(overlay);return;
    }
    // Paneles flotantes sin backdrop (Inventario y Guía): un click realmente exterior los cierra
    // y se consume para no activar accidentalmente algo del juego que estaba detrás.
    const floating=[lootPanel,el("infoPanel",game)].filter(x=>x&&!x.classList.contains("hidden"));
    for(let i=floating.length-1;i>=0;i--){const panel=floating[i];if(panel.contains(target))continue;
      const opener=target.closest?.("#lootBtn,#helpInfoBtn,#openIncenseInventoryBtn,#openMintInventoryBtn");if(opener)continue;
      e.preventDefault();e.stopPropagation();e.stopImmediatePropagation?.();johtoCloseSurfaceFromBackdrop(panel);return;
    }
  },true);
}
