y=cloneNode("body > #patchNotesOverlay");uxWhyOverlay=cloneNode("body > #uxWhyOverlay");uxCompareOverlay=cloneNode("body > #uxCompareOverlay");exitOverlay=cloneNode("body > #exitOverlay");firstWelcomeOverlay=cloneNode("body > #pkFirstWelcomeOverlay");achievementCornerPop=cloneNode("body > #achievementCornerPop");evolutionPopEl=cloneNode("body > #evolutionPop");mobileDock=cloneNode("body > #pkMobileDock");mobileMore=cloneNode("body > #pkMobileMore");mobileTip=cloneNode("body > #pkMobileTip");saveTransferOverlay=cloneNode("body > #saveTransferOverlay");backupOverlay=cloneNode("body > #pkBackupOverlay");diagnosticOverlay=null;cloudOverlay=cloneNode("body > #pkCloudOverlay");cloudConflictOverlay=cloneNode("body > #pkCloudConflictOverlay");casinoOverlay=cloneNode("body > #pkCasinoOverlay");
  const toastEl=document.createElement("div");toastEl.id="pkRuntimeToast";toastEl.className="toast pk-runtime-toast";root.appendChild(toastEl);
