function johtoUiHasPauseSurface(){return johtoUiPauseSurfaces().some(x=>!x.classList.contains("hidden"));}
function johtoFlushDeferredRunEnd(){
  if(!johtoDeferredRunEnd||johtoUiHasPauseSurface())return false;
  const d=johtoDeferredRunEnd;johtoDeferredRunEnd=null;johtoUiAutoPaused=false;
  if(d.kind==="failed")johtoShowRunFailedNow(d.dist,d.cp,d.snapshot);
  else johtoShowRunStoppedNow(d.snapshot);
  return true;
}
function johtoSyncUiPause(){
  const r=B()?.getRun?.(),blocked=johtoUiHasPauseSurface();
  if(blocked&&r&&!r.paused&&!r.rewardPending&&!r.centerPending){
    const paused=B()?.togglePause?.();
    if(paused===true)johtoUiAutoPaused=true;
  }else if(!blocked){
    if(johtoFlushDeferredRunEnd())return;
    if(johtoUiAutoPaused){
      const live=B()?.getRun?.();
      if(live?.paused&&!live.rewardPending&&!live.centerPending)B()?.togglePause?.();
      johtoUiAutoPaused=false;
    }
  }
}
function johtoInstallUiPauseGuard(){
  try{johtoUiPauseObserver?.disconnect?.();}catch(_){}
  johtoUiPauseObserver=new MutationObserver(()=>queueMicrotask(johtoSyncUiPause));
  for(const node of johtoUiPauseSurfaces())johtoUiPauseObserver.observe(node,{attributes:true,attributeFilter:["class"]});
  johtoSyncUiPause();
}
