async function johtoDialogPauseSnapshot(){
  const r=B()?.getRun?.(),g=B()?.getGymBattle?.(),snap={run:false,gym:false};
  if(r&&!r.paused&&!r.rewardPending&&!r.centerPending){try{snap.run=B()?.togglePause?.()===true;}catch(_){}}
  if(g&&!g.paused&&!g.finished){try{snap.gym=B()?.gymPause?.(true)===true;}catch(_){}}
  return snap;
}
function johtoDialogResumeSnapshot(snap){
  if(snap?.run){try{const r=B()?.getRun?.();if(r?.paused&&!r.rewardPending&&!r.centerPending)B()?.togglePause?.();}catch(_){}}
  if(snap?.gym){try{const g=B()?.getGymBattle?.();if(g?.paused&&!g.finished)B()?.gymPause?.(false);}catch(_){}}
}
async function johtoGameConfirm({title="Confirmar acción",message="",confirmText="Confirmar",cancelText="Cancelar",tone="primary",symbol="?"}={}){
  const snap=await johtoDialogPauseSnapshot();
  try{
    const fn=window.PokeSendaGameConfirm;
    if(typeof fn==="function")return !!(await fn({title,message,confirmText,cancelText,tone,symbol}));
    return !!window.confirm(message);
  }finally{johtoDialogResumeSnapshot(snap);}
}
async function johtoGameAlert({title="PokéSenda",message="",confirmText="Cerrar",tone="primary",symbol="ℹ️"}={}){
  const snap=await johtoDialogPauseSnapshot();
  try{
    const fn=window.PokeSendaGameAlert;
    if(typeof fn==="function"){await fn({title,message,confirmText,tone,symbol});return true;}
    const cf=window.PokeSendaGameConfirm;
    if(typeof cf==="function"){await cf({title,message,confirmText,cancelText:"",tone,symbol,showCancel:false});return true;}
    window.alert(message);return true;
  }finally{johtoDialogResumeSnapshot(snap);}
}

