  const play=el("menuPlayBtn",menu);if(play){play.textContent="Jugar";play.onclick=showGame;}
  const opt=el("menuOptionsBtn",menu);if(opt){opt.textContent="Opciones";opt.onclick=openOptions;}
  const prof=el("menuProfileBtn",menu);if(prof){prof.disabled=false;prof.textContent="Perfil";prof.onclick=()=>openRegionalProfile("menu");}
