function regionalizeTextTree(scope){
  if(!scope)return;const walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  const reps=[["Ruta Verde","Pradera Ámbar"],["Cueva Rocosa","Bosque Ancestral"],["Costa Azul","Senda Plateada"],["Kanto","Johto"],["151 Pokémon","131 Pokémon regionales"],["151/151","131/131"]];
  for(const n of nodes){let t=n.nodeValue;for(const [a,b] of reps)t=t.split(a).join(b);n.nodeValue=t;}
}
