// Diagnóstico regional retirado de la build pública.
const JOHTO_BACKUP_KEY="pokesenda_johto_backups_v1";
function johtoSaveSummary(s=read()){
  const name=String(s?.trainerAvatar?.name||s?.trainerName||"Entrenador"),owned=Object.keys(s?.pokemon||{}).length,money=Math.floor(Number(s?.money||0)).toLocaleString("es-CL"),routes=JOHTO_ROUTE_ORDER.reduce((n,id)=>n+Number(s?.routes?.[id]?.completions||0),0);
  return `${name} · ${owned} Pokémon · ₽${money} · ${routes} rutas completadas`;
}
function johtoTransferPayload(){return{format:"PokeSendaJohtoSave",formatVersion:1,region:"johto",gameVersion:"V36.64.9",exportedAt:new Date().toISOString(),data:read()};}
function johtoSaveFileName(){const d=new Date(),pad=n=>String(n).padStart(2,"0");return `PokeSenda_Johto_Save_${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}_${pad(d.getHours())}-${pad(d.getMinutes())}.pokesenda`;}
function johtoPayloadFile(){return new File([JSON.stringify(johtoTransferPayload())],johtoSaveFileName(),{type:"application/json"});}
function johtoDownloadSave(){try{const file=johtoPayloadFile(),url=URL.createObjectURL(file),a=document.createElement("a");a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast("💾 Partida de Johto exportada");refreshJohtoTransferStatus();return true;}catch(_){toast("No se pudo exportar la partida de Johto");return false;}}
async function johtoShareSave(){try{const file=johtoPayloadFile();if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]})))await navigator.share({title:"Partida de PokéSenda · Johto",text:"Respaldo de mi campaña de Johto",files:[file]});else johtoDownloadSave();return true;}catch(e){if(e?.name!=="AbortError")toast("No se pudo compartir el respaldo");return false;}}
function readJohtoBackups(){try{const a=JSON.parse(localStorage.getItem(JOHTO_BACKUP_KEY)||"[]");return Array.isArray(a)?a:[];}catch(_){return[];}}
function writeJohtoBackups(a){try{localStorage.setItem(JOHTO_BACKUP_KEY,JSON.stringify(a.slice(0,3)));return true;}catch(_){try{localStorage.setItem(JOHTO_BACKUP_KEY,JSON.stringify(a.slice(0,2)));return true;}catch(__){return false;}}}
function createJohtoBackup(reason="Respaldo manual",silent=false){try{const raw=localStorage.getItem(SAVE);if(!raw)return false;const list=readJohtoBackups();if(list[0]?.raw===raw){if(!silent)toast("🛡️ La partida actual de Johto ya está respaldada");renderJohtoBackups();return true;}const item={createdAt:new Date().toISOString(),reason:String(reason).slice(0,120),gameVersion:"V36.64.9",raw},ok=writeJohtoBackups([item,...list]);if(!silent)toast(ok?"🛡️ Respaldo Johto creado":"No se pudo crear el respaldo Johto");renderJohtoBackups();return ok;}catch(_){if(!silent)toast("No se pudo crear el respaldo Johto");return false;}}
async function johtoConfirmAction(title,message,confirmText="Confirmar"){
  const fn=window.PokeSendaGameConfirm||window.gameConfirm;if(typeof fn==="function")try{return await fn({title,message,confirmText,cancelText:"Cancelar",tone:"danger",symbol:"🛡️"});}catch(_){}
  return window.confirm(message);
}
function renderJohtoBackups(){if(!backupOverlay)return;const box=el("pkBackupList",backupOverlay),list=readJohtoBackups();if(!box)return;if(!list.length){box.innerHTML='<div class="pk-backup-empty">Todavía no hay respaldos locales de Johto. Puedes crear uno manualmente antes de una importación o cambio importante.</div>';return;}box.innerHTML=list.map((x,i)=>{let summary="Partida Johto";try{summary=johtoSaveSummary(JSON.parse(x.raw));}catch(_){}return '<div class="pk-backup-card"><div><b>'+htmlSafe(new Date(x.createdAt).toLocaleString("es-CL"))+'</b><span>'+htmlSafe(summary)+'</span><small>'+htmlSafe(x.reason||"Respaldo")+' · '+htmlSafe(x.gameVersion||"")+'</small></div><button class="btn" type="button" data-j-backup-restore="'+i+'">Restaurar</button></div>';}).join("");qa("[data-j-backup-restore]",box).forEach(b=>b.onclick=()=>restoreJohtoBackup(Number(b.dataset.jBackupRestore)));}
async function restoreJohtoBackup(index){const list=readJohtoBackups(),item=list[index];if(!item?.raw)return;let summary="Partida Johto";try{summary=johtoSaveSummary(JSON.parse(item.raw));}catch(_){}const ok=await johtoConfirmAction("Restaurar respaldo · Johto","Se reemplazará solamente la campaña de Johto por el respaldo del "+new Date(item.createdAt).toLocaleString("es-CL")+".\n\n"+summary+"\n\nKanto no se modificará.","Restaurar Johto");if(!ok)return;try{const current=localStorage.getItem(SAVE);if(current&&current!==item.raw)writeJohtoBackups([{createdAt:new Date().toISOString(),reason:"Antes de restaurar otro respaldo",gameVersion:"V36.64.9",raw:current},...list]);B()?.stop?.(true);(window.PokeSendaSaveGuard?.withBypass?window.PokeSendaSaveGuard.withBypass(()=>localStorage.setItem(SAVE,item.raw)):localStorage.setItem(SAVE,item.raw));B()?.reload?.();backupOverlay.classList.add("hidden");showLobby();toast("✅ Respaldo de Johto restaurado");}catch(_){toast("No se pudo restaurar el respaldo Johto");}}
function refreshJohtoTransferStatus(){if(!saveTransferOverlay)return;const status=el("saveTransferStatus",saveTransferOverlay);if(status)status.innerHTML='<b>Partida local de Johto:</b> '+htmlSafe(johtoSaveSummary())+'<br><small>Exportar/importar afecta solamente al save regional de Johto. Kanto permanece intacto.</small>';}
async function importJohtoText(rawText,fileName="respaldo"){let parsed;try{parsed=JSON.parse(rawText);}catch(_){toast("El archivo no contiene un save válido");return false;}if(parsed?.format==="PokeSendaSave"||parsed?.region==="kanto"){toast("Ese archivo corresponde a Kanto. No se importó en Johto.");return false;}const candidate=parsed?.format==="PokeSendaJohtoSave"?parsed.data:parsed;if(!candidate||typeof candidate!=="object"||Array.isArray(candidate)||!candidate.routes||!candidate.pokemon||!Array.isArray(candidate.formation)||!["j_chikorita","j_cyndaquil","j_totodile"].includes(candidate.starter)){toast("El archivo no parece ser una partida válida de Johto");return false;}const ok=await johtoConfirmAction("Importar partida · Johto","Se reemplazará solamente el progreso de Johto por:\n\n"+johtoSaveSummary(candidate)+"\n\nArchivo: "+fileName+"\n\nKanto no se modificará.","Importar Johto");if(!ok)return false;try{createJohtoBackup("Antes de importar "+fileName,true);B()?.stop?.(true);(window.PokeSendaSaveGuard?.withBypass?window.PokeSendaSaveGuard.withBypass(()=>localStorage.setItem(SAVE,JSON.stringify(candidate))):localStorage.setItem(SAVE,JSON.stringify(candidate)));B()?.reload?.();saveTransferOverlay.classList.add("hidden");showLobby();toast("✅ Partida de Johto importada");return true;}catch(_){toast("No se pudo guardar la partida importada");return false;}}
function openJohtoTransferParity(){if(!saveTransferOverlay)return;refreshJohtoTransferStatus();saveTransferOverlay.classList.remove("hidden");}
