  const weak={j_chikorita:"j_totodile",j_cyndaquil:"j_chikorita",j_totodile:"j_cyndaquil"},strong={j_chikorita:"j_cyndaquil",j_cyndaquil:"j_totodile",j_totodile:"j_chikorita"};
