  if(tier===4){for(const r of order)pools[r]=[...full[r]];}else{const regular=[];for(const r of ["common","uncommon","rare","epic"])for(const id of full[r])regular.push({id,rarity:r});const limit=tier===1?Math.ceil(regular.length/3):tier===2?Math.ceil(regular.length*2/3):regular.length;for(const x of regular.slice(0,limit))pools[x.rarity].push(x.id);}
