  const desc=el("routeDescription",page),pool=el("poolList",page),boss=johtoHelpBossName(route),sectors=(route.sectors||[]).join(" → "),r=B()?.getRun?.(),km=Math.max(1,Math.min(10,Math.floor(Number(r?.distance||0)/1000)+1));
