function canEditTeam(){const r=B()?.getUiRun?.()??B()?.getRun?.();return !r||!!r.paused;}
let johtoFormationDragSession=null;
function johtoCancelFormationDrag(){
  const d=johtoFormationDragSession;johtoFormationDragSession=null;
  if(!d)return;
  try{d.abort?.abort?.();}catch(_){}
  try{if(d.handle?.hasPointerCapture?.(d.pointerId))d.handle.releasePointerCapture(d.pointerId);}catch(_){}
  try{d.ghost?.remove?.();}catch(_){}
  try{d.sourceSlot?.classList.remove('formation-dragging');}catch(_){}
  try{d.targetSlot?.classList.remove('formation-drop-target');}catch(_){}
  document.documentElement.classList.remove('pk-formation-pointer-drag');
}
window.PokeSendaCancelJohtoFormationDrag=johtoCancelFormationDrag;
function johtoInstallFormationDrag(){
  const wrap=game&&el('formationControls',game);if(!wrap||wrap.dataset.johtoDragDelegate==='2')return;
  // La Formación de Johto se reconstruye con innerHTML, pero este contenedor persiste.
  // Un único listener delegado evita listeners clonados/perdidos al cambiar de región o renderizar.
  wrap.dataset.johtoDragDelegate='2';
  wrap.addEventListener('pointerdown',e=>{
    const handle=e.target?.closest?.('.formation-pokemon');
    if(!handle||!wrap.contains(handle)||!canEditTeam())return;
    if(e.pointerType==='mouse'&&e.button!==0)return;
    johtoCancelFormationDrag();
    const slots=[...wrap.querySelectorAll('.formation-slot')],sourceSlot=handle.closest('.formation-slot'),from=slots.indexOf(sourceSlot);
    if(from<0)return;
    const rect=handle.getBoundingClientRect(),pointerId=e.pointerId,startX=e.clientX,startY=e.clientY,grabX=e.clientX-rect.left,grabY=e.clientY-rect.top;
    const abort=new AbortController(),signal=abort.signal;
    let dragging=false,ghost=null,targetSlot=null,to=-1;
    const clearTarget=()=>{if(targetSlot)targetSlot.classList.remove('formation-drop-target');targetSlot=null;to=-1;};
    const moveGhost=(x,y)=>{if(ghost)ghost.style.transform=`translate3d(${Math.round(x-grabX)}px,${Math.round(y-grabY)}px,0) scale(1.02)`;};
    const pickTarget=(x,y)=>{const hit=document.elementFromPoint(x,y),slot=hit?.closest?.('.formation-slot');if(!slot||!wrap.contains(slot)||slot===sourceSlot){clearTarget();return;}const idx=slots.indexOf(slot);if(idx<0){clearTarget();return;}if(targetSlot!==slot){clearTarget();targetSlot=slot;to=idx;slot.classList.add('formation-drop-target');}};
    const begin=()=>{if(dragging)return;dragging=true;sourceSlot.classList.add('formation-dragging');document.documentElement.classList.add('pk-formation-pointer-drag');ghost=handle.cloneNode(true);ghost.removeAttribute('id');ghost.removeAttribute('data-open-pokemon');ghost.removeAttribute('data-j-pokemon');ghost.removeAttribute('data-j-form-mon');ghost.classList.remove('formation-drag-handle');ghost.classList.add('pk-formation-drag-ghost');ghost.style.width=rect.width+'px';ghost.style.height=rect.height+'px';document.body.appendChild(ghost);moveGhost(startX,startY);};
    const cleanup=()=>{try{abort.abort();}catch(_){}try{if(handle.hasPointerCapture?.(pointerId))handle.releasePointerCapture(pointerId);}catch(_){}ghost?.remove();sourceSlot.classList.remove('formation-dragging');clearTarget();document.documentElement.classList.remove('pk-formation-pointer-drag');if(johtoFormationDragSession?.abort===abort)johtoFormationDragSession=null;};
    const finish=(commit,ev)=>{if(ev&&ev.pointerId!==pointerId)return;const target=to,wasDragging=dragging;if(wasDragging){handle.addEventListener('click',ce=>{ce.preventDefault();ce.stopImmediatePropagation();},{capture:true,once:true});}cleanup();if(commit&&wasDragging&&target>=0&&target!==from&&canEditTeam())swapFormationSlotsJohto(from,target);};
    const move=ev=>{if(ev.pointerId!==pointerId)return;const dist=Math.hypot(ev.clientX-startX,ev.clientY-startY);if(!dragging&&dist<5)return;if(!dragging)begin();ev.preventDefault();moveGhost(ev.clientX,ev.clientY);pickTarget(ev.clientX,ev.clientY);};
    johtoFormationDragSession={abort,handle,pointerId,sourceSlot,get targetSlot(){return targetSlot},get ghost(){return ghost}};
    try{handle.setPointerCapture?.(pointerId);}catch(_){}
    window.addEventListener('pointermove',move,{capture:true,passive:false,signal});
    window.addEventListener('pointerup',ev=>finish(true,ev),{capture:true,signal});
    window.addEventListener('pointercancel',ev=>finish(false,ev),{capture:true,signal});
    handle.addEventListener('lostpointercapture',ev=>{if(ev.pointerId===pointerId)finish(false,ev);},{signal});
    window.addEventListener('blur',()=>finish(false),{signal});
    window.addEventListener('keydown',ev=>{if(ev.key==='Escape')finish(false);},{capture:true,signal});
    document.addEventListener('visibilitychange',()=>{if(document.hidden)finish(false);},{signal});
  },true);
}
