function johtoRouteStarterFamily(routeId,s=read()){
  const c=s.starter;if(!c)return null;
  if(routeId==="johto_route1")return c;
  const weak={j_chikorita:"j_totodile",j_cyndaquil:"j_chikorita",j_totodile:"j_cyndaquil"};
  const strong={j_chikorita:"j_cyndaquil",j_cyndaquil:"j_totodile",j_totodile:"j_chikorita"};
  return routeId==="johto_route2"?weak[c]:routeId==="johto_route3"?strong[c]:null;
}
function johtoRoutePoolFamilyIds(routeId="johto_route1"){
  const r=D().routes?.[routeId]||{},out=[];
  for(const ids of Object.values(r.gachaByRarity||{}))for(const id of ids||[])if(id&&!out.includes(id))out.push(id);
  const starter=johtoRouteStarterFamily(routeId);if(starter&&!out.includes(starter))out.push(starter);
  return out;
}
