function achTarget(d){const x=typeof d.target==="function"?d.target():d.target;return Math.max(1,Number(x)||1);}
function achValue(d,s=read()){try{return Math.max(0,Number(d.val(s))||0)}catch(_){return 0}}
function achCash(d){
  if(Number.isFinite(Number(d.cash)))return Math.max(0,Math.floor(Number(d.cash)));
  const p=Number(d.points||0);if(p<=5)return 2500;if(p<=10)return 5000;if(p<=15)return 7500;if(p<=20)return 10000;if(p<=25)return 15000;if(p<=30)return 20000;if(p<=35)return 25000;if(p<=45)return 40000;if(p<=50)return 50000;if(p<=60)return 65000;if(p<=75)return 85000;return 125000;
}
function achPoints(s=read()){return J_ACH.reduce((n,d)=>n+(s.achievements?.unlocked?.[d.id]?Number(d.points||0):0),0);}
function ensureAchievementShape(s){
  s.achievements=s.achievements&&typeof s.achievements==="object"?s.achievements:{};
  const a=s.achievements;
  a.unlocked=a.unlocked&&typeof a.unlocked==="object"?a.unlocked:{};
  a.unread=Array.isArray(a.unread)?a.unread:[];
  a.claimedRewards=Array.isArray(a.claimedRewards)?a.claimedRewards:[];
  a.claimedMilestones=Array.isArray(a.claimedMilestones)?a.claimedMilestones:[];
  a.premiumTickets=Math.max(0,Math.floor(Number(a.premiumTickets||0)));
  a.shinyTickets=Math.max(0,Math.floor(Number(a.shinyTickets||0)));
  a.tmChoices=a.tmChoices&&typeof a.tmChoices==="object"?a.tmChoices:{};
  return a;
}
const JOHTO_TO_HOENN_REWARD_KEY="pokesenda_cross_region_rewards_v1",HOENN_ACHIEVEMENT_SAVE_KEY="pokesenda_hoenn_isolated_v1";
function johtoGrantHoennPremiumTickets(amount,sourceId){
  amount=Math.max(0,Math.floor(Number(amount)||0));if(!amount)return 0;sourceId=String(sourceId||"");
  try{
    const raw=localStorage.getItem(HOENN_ACHIEVEMENT_SAVE_KEY);
    if(raw){
      const hs=JSON.parse(raw)||{};hs.achievements=hs.achievements&&typeof hs.achievements==="object"?hs.achievements:{};
      hs.achievements.premiumTickets=Math.max(0,Math.floor(Number(hs.achievements.premiumTickets||0)));
      hs.crossRegionRewards=hs.crossRegionRewards&&typeof hs.crossRegionRewards==="object"?hs.crossRegionRewards:{claimedJohtoAchievements:[]};
      const claimed=Array.isArray(hs.crossRegionRewards.claimedJohtoAchievements)?hs.crossRegionRewards.claimedJohtoAchievements:[];
      if(sourceId&&claimed.includes(sourceId))return 0;
      hs.achievements.premiumTickets+=amount;if(sourceId)claimed.push(sourceId);
      hs.crossRegionRewards.claimedJohtoAchievements=[...new Set(claimed)];
      localStorage.setItem(HOENN_ACHIEVEMENT_SAVE_KEY,JSON.stringify(hs));return amount;
    }
  }catch(_){}
  try{
    const q=JSON.parse(localStorage.getItem(JOHTO_TO_HOENN_REWARD_KEY)||"{}");
    q.hoennPremiumTickets=Math.max(0,Math.floor(Number(q.hoennPremiumTickets||0)));
    q.claimedJohtoAchievements=Array.isArray(q.claimedJohtoAchievements)?q.claimedJohtoAchievements:[];
    if(sourceId&&q.claimedJohtoAchievements.includes(sourceId))return 0;
    q.hoennPremiumTickets+=amount;if(sourceId)q.claimedJohtoAchievements.push(sourceId);
    q.claimedJohtoAchievements=[...new Set(q.claimedJohtoAchievements)];
    localStorage.setItem(JOHTO_TO_HOENN_REWARD_KEY,JSON.stringify(q));return amount;
  }catch(_){return 0;}
}
