function checkAchievements(){
  const s=read(),a=ensureAchievementShape(s),newDefs=[];let changed=false;
  for(const d of J_ACH){
    if(a.unlocked[d.id])continue;
    if(achValue(d,s)>=achTarget(d)){a.unlocked[d.id]=Date.now();if(!a.unread.includes(d.id))a.unread.push(d.id);newDefs.push(d);changed=true;}
  }
  if(changed){
    /* El estado de Johto es vivo: persistimos el mismo objeto y evitamos recargar el motor
       sólo para registrar un Logro. Esto mantiene contadores de Gimnasio/ruta sincronizados. */
    write(s);renderAchievementAlert();showAchievementCorner(newDefs);
  }
  return changed;
}
function achievementClaimable(s=read()){const a=ensureAchievementShape(s),claimed=new Set(a.claimedRewards);return J_ACH.filter(d=>a.unlocked[d.id]&&!claimed.has(d.id));}
function achievementRoadClaimable(s=read()){const a=ensureAchievementShape(s),pts=achPoints(s),claimed=new Set(a.claimedMilestones);return J_ROAD.filter(m=>pts>=m.points&&!claimed.has(m.id));}
function renderAchievementAlert(){
  const s=read(),a=ensureAchievementShape(s),n=a.unread.length+achievementClaimable(s).length+achievementRoadClaimable(s).length;
  for(const host of [game,menu]){const e=host?el(host===game?"achievementAlert":"menuAchievementAlert",host):null;if(!e)continue;e.classList.toggle("hidden",!n);e.classList.add("ux-new-counter");e.textContent=n?`NUEVO ${n>99?"99+":n}`:"";e.title=n?`${n} novedad${n===1?"":"es"} por revisar`:"";}
}
