  el("evolveNoBtn",evolutionOverlay).textContent=c.auto?'No evolucionar':'Cancelar';el("evolveYesBtn",evolutionOverlay).disabled=!opt.ready;el("evolveYesBtn",evolutionOverlay).textContent='Evolucionar';qa("[data-j-evo-choice]",evolutionOverlay).forEach(b=>b.onclick=()=>{c.selected=Number(b.dataset.jEvoChoice);renderEvolutionOverlay();});
