function skillRankRuntime(id){return Math.max(0,Number(read().skillTree?.[id]||0));}
function skillUnlockedRuntime(id){const n=SKILL_NODES[id];return !!n&&n.requires.every(([r,k])=>skillRankRuntime(r)>=k);}
