function skillCostRuntime(id){const n=SKILL_NODES[id],r=skillRankRuntime(id);if(Array.isArray(n.costs)&&n.costs.length)return Math.round(Number(n.costs[Math.min(r,n.costs.length-1)]||0));if(id==="trainer")return 1000;if(n?.max===1&&TREE_MAJOR_COSTS_RUNTIME[id]!=null)return TREE_MAJOR_COSTS_RUNTIME[id];const mult=n.branch==="automation"?6.40:6.00,growth=1.46;return Math.round(n.baseCost*mult*Math.pow(r+1,growth));}
