function johtoBattleFx(ev){try{if(!ev||currentView!=="game")return;const s=read(),field=el("field",game);if(!field)return;const ally=id=>q('[data-j-world-id="'+CSS.escape(String(id))+'"] .mon',game),enemy=uid=>q('[data-j-enemy-uid="'+CSS.escape(String(uid))+'"] .enemy',game);if(ev.kind==="attack"&&s.options?.animations!==false){const src=ev.side==="player"?ally(ev.sourceId):enemy(ev.sourceUid),targets=ev.side==="player"?(ev.targetUids||[]).map(enemy):(ev.targetIds||[]).map(ally);targets.filter(Boolean).forEach((t,i)=>johtoProjectile(src,t,ev.moveType,i*28));}else if(ev.kind==="hit"){const node=ev.side==="player"?ally(ev.targetId):enemy(ev.targetUid);let cls=ev.crit?"crit":ev.status==="burn"?"burn":ev.status==="poison"?"poison":Number(ev.eff)>1.01?"super":Number(ev.eff)<.99?"resist":"",color=TYPE_COLOR[ev.moveType]||"#fff";johtoSpawnFloat(node,"-"+Math.max(1,Math.ceil(Number(ev.amount)||0)),cls,color);if(s.options?.animations!==false&&node){node.classList.remove("hit-react");void node.offsetWidth;node.classList.add("hit-react");setTimeout(()=>node.classList.remove("hit-react"),300);}}else if(ev.kind==="heal")johtoSpawnFloat(ally(ev.targetId),"+"+Math.max(1,Math.ceil(Number(ev.amount)||0)),"heal");else if(ev.kind==="miss"){const node=ev.targetUid?enemy(ev.targetUid):ally(ev.targetId);johtoSpawnFloat(node,"FALLO","resist");}else if(ev.kind==="immune")johtoSpawnFloat(ally(ev.targetId),"INMUNE","resist");}catch(_){}}
